WITH metrics AS (SELECT *, NTILE(5) OVER w_recent AS discount_pct_bucket, SUM(discount_pct) OVER (PARTITION BY promo_code ORDER BY discount_pct, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_discount_pct FROM promotions WINDOW w_recent AS (PARTITION BY promo_code ORDER BY discount_pct DESC, id)) SELECT id, channel, starts_on, ends_on, running_discount_pct FROM metrics ORDER BY starts_on DESC;
